// @generated by:gauntlet run:godseye-local-hermes-chat
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { expect, it } from "vitest";
import { createHermesProvider } from "../apps/control-api/src/hermes-provider.js";
import type {
  AgentObservation,
  AgentProviderRequest,
} from "../packages/core/src/agents-provider.js";
import { providerRequest } from "../packages/core/src/agents-state.js";
import { agentsFixture, controlled } from "./helpers/agents-fixture.js";
import { nativeModelFixture } from "./helpers/agents-native-fixture.js";

const native = process.env.GODSEYE_TEST_HERMES_CHAT_NATIVE === "1";
const digest = (text: string) => createHash("sha256").update(text).digest("hex");

it.skipIf(!native)(
  "T-AC-743 actual Hermes publishes incremental text before held completion and preserves the next explicit context",
  async () => {
    const fixture = await agentsFixture();
    const model = await nativeModelFixture({ incrementalReply: true });
    const provider = createHermesProvider({
      fixtureBaseUrl: model.baseUrl,
      bindings: [
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          role: "operations",
          apiKey: randomBytes(24).toString("hex"),
        },
      ],
    });
    const abort = new AbortController();
    const firstInput = "First explicit native chat question.";
    const firstAnswer = "Hermes native fixture finished safely.";
    const secondInput = "Second explicit native chat question.";
    const conversationId = randomUUID();
    const progress: { sequence: number; text: string; providerRunId: string }[] = [];
    const firstDelta = controlled<void>();
    let authorizations = 0;
    async function finish(request: AgentProviderRequest, initial: AgentObservation) {
      let observation = initial;
      while (
        ["running", "unknown"].includes(observation.state) &&
        Date.now() < Date.parse(request.deadline)
      ) {
        await new Promise((done) => setTimeout(done, 100));
        observation = await provider.inspect(
          { ...request, providerRunId: observation.providerRunId },
          abort.signal,
        );
      }
      expect(observation).toMatchObject({ state: "succeeded", stopped: true, output: firstAnswer });
      return observation;
    }
    try {
      const profile = await fixture.create({
        limits: { ...fixture.profileInput.limits, timeoutSeconds: 120 },
      });
      const task = await fixture.launch(profile.id, profile.revision, firstInput);
      const [row] = await fixture.store.db
        .select()
        .from(schema.agentTasks)
        .where(eq(schema.agentTasks.id, task.id));
      if (!row) throw new Error("Native chat task was not journaled");
      const request: AgentProviderRequest = {
        ...providerRequest(row),
        deadline: new Date(Date.now() + 120000).toISOString(),
        conversation: { id: conversationId, history: [] },
      };
      const initial = await provider.submit(request, {
        signal: abort.signal,
        assertActive: async () => {
          authorizations++;
        },
        onEvent: async (event) => {
          progress.push(event);
          firstDelta.resolve();
        },
      });
      await Promise.race([
        firstDelta.promise,
        new Promise<never>((_resolve, reject) => {
          const timer = setTimeout(
            () => reject(new Error("No actual text before held completion")),
            45000,
          );
          timer.unref();
        }),
      ]);
      expect(progress.map((event) => event.text).join("")).toBe("Hermes native ");
      expect(progress[0]?.providerRunId).toMatch(/^run_[a-f0-9]{32}$/);
      const beforeRelease = await provider.inspect(
        { ...request, providerRunId: initial.providerRunId },
        abort.signal,
      );
      expect(beforeRelease.state).not.toBe("succeeded");
      expect(beforeRelease.stopped).toBe(false);
      expect((await model.stats()) as { requests: unknown[] }).toMatchObject({
        requests: [expect.any(Object)],
      });
      await model.release();
      await finish(request, beforeRelease);
      expect(progress.map((event) => event.text).join("")).toBe(firstAnswer);
      expect(
        progress.every(
          (event, index) => index === 0 || event.sequence > (progress[index - 1]?.sequence ?? -1),
        ),
      ).toBe(true);

      const secondId = randomUUID();
      const second: AgentProviderRequest = {
        ...request,
        taskId: secondId,
        correlationId: secondId,
        providerRunId: null,
        input: secondInput,
        deadline: new Date(Date.now() + 120000).toISOString(),
        conversation: {
          id: conversationId,
          history: [
            { role: "user", content: firstInput },
            { role: "assistant", content: firstAnswer },
          ],
        },
      };
      await finish(
        second,
        await provider.submit(second, {
          signal: abort.signal,
          assertActive: async () => {
            authorizations++;
          },
          onEvent: async () => {},
        }),
      );
      const stats = (await model.stats()) as {
        requests: {
          model: string;
          tools: boolean;
          maxOutputTokens: number;
          skillLoaded: boolean;
          messages: { role: string; sha256: string }[];
        }[];
      };
      expect(stats.requests).toHaveLength(2);
      for (const modelRequest of stats.requests)
        expect(modelRequest).toMatchObject({
          model: "gpt-6-luna",
          tools: false,
          maxOutputTokens: 1024,
          skillLoaded: true,
        });
      expect(stats.requests[1]?.messages).toEqual(
        expect.arrayContaining([
          { role: "user", sha256: digest(firstInput) },
          { role: "assistant", sha256: digest(firstAnswer) },
          { role: "user", sha256: digest(secondInput) },
        ]),
      );
      expect(authorizations).toBeGreaterThanOrEqual(6);
      console.info(
        JSON.stringify({
          kind: "native-chat-qualification",
          actualRequests: stats.requests.length,
          incrementalFrames: progress.length,
          partialBeforeRelease: true,
          contextHashesMatched: true,
        }),
      );
    } finally {
      abort.abort();
      await model.release();
      await provider.close();
      await model.close();
      await fixture.store.close();
    }
  },
  300000,
);

